    "createTime" TIMESTAMP                                                      DEFAULT NULL,
    "updateTime" TIMESTAMP                                                      DEFAULT NULL
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_general_ci;

CREATE TABLE "department"
(
