    "remark" varchar(255) DEFAULT NULL COMMENT '备注',
    PRIMARY KEY ("id"),
    CONSTRAINT "employeeec_ibfk_1" FOREIGN KEY ("eid") REFERENCES "employee" ("id")
);

CREATE TABLE "employeeremove"
